  "학기마다 과목별 강의 목표와 주차별 교육 내용을 관리합니다.": "စာသင်ကာလတစ်ခုစီတွင် ဘာသာရပ်အလိုက် သင်ကြားရေးရည်မှန်းချက်နှင့် အပတ်စဉ်သင်ခန်းစာအကြောင်းအရာများကို စီမံပါသည်။",
  "학과 미지정": "ဌာန မသတ်မှတ်ရသေးပါ",
  "담당 교수 미지정": "တာဝန်ခံဆရာ/ဆရာမ မသတ်မှတ်ရသေးပါ",
  "교수는 선택한 학기·과목에 배정된 교수만 선택할 수 있습니다. 시간표와 강의실·교수의 시간 충돌은 저장 단계에서 검사합니다.": "ရွေးချယ်ထားသော စာသင်ကာလနှင့် ဘာသာရပ်တွင် တာဝန်ပေးထားသော ဆရာ/ဆရာမများကိုသာ ရွေးချယ်နိုင်ပါသည်။ အချိန်ဇယား၊ စာသင်ခန်းနှင့် ဆရာ/ဆရာမတို့၏ အချိန်တိုက်ဆိုင်မှုကို သိမ်းဆည်းချိန်တွင် စစ်ဆေးပါသည်။",
  "현재 선택한 학과의 주간 시간표를 대상 학기로 복사합니다. 대상 학기에 이미 시간표가 있거나 강의실·교수 시간이 겹치면 전체 복사가 취소됩니다.": "လက်ရှိရွေးချယ်ထားသော ဌာန၏ အပတ်စဉ်အချိန်ဇယားကို သတ်မှတ်ထားသော စာသင်ကာလသို့ ကူးယူပါသည်။ သတ်မှတ်စာသင်ကာလတွင် အချိန်ဇယားရှိပြီးသားဖြစ်ပါက သို့မဟုတ် စာသင်ခန်း/ဆရာအချိန် တိုက်ဆိုင်ပါက ကူးယူမှုတစ်ခုလုံးကို ပယ်ဖျက်ပါသည်။",
  "담당 교수 선택": "တာဝန်ခံဆရာ/ဆရာမ ရွေးချယ်ရန်",
  "주차별 내용을 한 줄씩 입력하면 순서대로 주차가 지정됩니다.": "အပတ်စဉ်အကြောင်းအရာကို တစ်ကြောင်းစီ ထည့်သွင်းပါက အစဉ်လိုက် အပတ်နံပါတ် သတ်မှတ်ပေးပါသည်။",
  "시수는 주당 기준으로 입력합니다. 동일 과목에 여러 교수를 배정할 수 있습니다.": "သင်ကြားချိန်ကို တစ်ပတ်စာအလိုက် ထည့်သွင်းပါ။ ဘာသာရပ်တစ်ခုတည်းတွင် ဆရာ/ဆရာမများစွာကို တာဝန်ပေးနိုင်ပါသည်။",
