  "새 비밀번호를 설정하면 기존 비밀번호는 즉시 사용할 수 없게 됩니다.": "စကားဝှက်အသစ် သတ်မှတ်ပါက ယခင်စကားဝှက်ကို ချက်ချင်း အသုံးပြု၍မရတော့ပါ။",
  "기본 역할 권한을 이 회원에게만 별도로 허용하거나 차단할 수 있습니다. 개별 설정은 역할 기본값보다 우선합니다.": "မူလတာဝန်အခန်းကဏ္ဍခွင့်ပြုချက်ကို ဤအသင်းဝင်တစ်ဦးတည်းအတွက် သီးခြားခွင့်ပြုခြင်း သို့မဟုတ် ပိတ်ပင်ခြင်း ပြုလုပ်နိုင်ပါသည်။ တစ်ဦးချင်းသတ်မှတ်ချက်သည် မူလအခန်းကဏ္ဍသတ်မှတ်ချက်ထက် ဦးစားပေးပါသည်။",
