const MY_FRAGMENTS=Object.entries(MY)
  .filter(([source,target])=>/[가-힣]/.test(source)&&source.length>1&&source!==target)
  .sort(([a],[b])=>b.length-a.length);

function localizedValue(raw:string){
  const key=raw.trim();
  if(!key) return raw;
  const exact=MY[key]||MY[key.replace(/\s+/g," ")];
  if(exact) return raw.replace(key,exact);
  if(!/[가-힣]/.test(raw)) return raw;
  let localized=raw;
  for(const [source,target] of MY_FRAGMENTS){
    if(localized.includes(source)) localized=localized.split(source).join(target);
  }
  return localized;
}



function translateText(node:Text){
  const parent=node.parentElement;
  if(!parent||parent.closest("script,style,textarea,[contenteditable=true],.notranslate,[data-no-translate]")) return;
  const raw=node.nodeValue??"";
  const translated=localizedValue(raw);
  if(translated!==raw) node.nodeValue=translated;
}

function translateAttributes(el:Element){
  if(!(el instanceof HTMLElement)||el.closest("script,style,[contenteditable=true],.notranslate,[data-no-translate]")) return;
  for(const attr of ["placeholder","title","aria-label"]){
    const value=el.getAttribute(attr);
    if(value){
      const translated=localizedValue(value);
      if(translated!==value) el.setAttribute(attr,translated);
    }
  }
}

function translateElement(el:Element){
  translateAttributes(el);
  const elements=document.createTreeWalker(el,NodeFilter.SHOW_ELEMENT);
  while(elements.nextNode()) translateAttributes(elements.currentNode as Element);
  const walker=document.createTreeWalker(el,NodeFilter.SHOW_TEXT);
  while(walker.nextNode()) translateText(walker.currentNode as Text);
}

function translateNode(node:Node){
  if(node.nodeType===Node.TEXT_NODE){translateText(node as Text);return;}
  if(node.nodeType===Node.ELEMENT_NODE) translateElement(node as Element);
}

export default function AdminMyanmarTranslator({locale}:{locale:string}){
  useEffect(()=>{
    if(locale!=="my") return;
    const root=document.querySelector(".admin")??document.body;
    translateElement(root);
    void fetch("/api/admin/data/website",{cache:"no-store",credentials:"same-origin",headers:{Accept:"application/json"}})
      .then(async response=>({response,data:await response.json().catch(()=>null)}))
      .then(({response,data})=>{
        if(!response.ok)return;
        const row=data?.items?.data?.find((item:{content_type?:string;content_key?:string;locale?:string})=>item.content_type==="page"&&item.content_key==="admin-translations"&&item.locale==="my");
        if(!row?.body)return;
        const overrides=JSON.parse(row.body);
        if(!overrides||typeof overrides!=="object")return;
        for(const [source,target] of Object.entries(overrides))if(typeof target==="string"&&target.trim())MY[source]=target;
        translateElement(root);
      }).catch(()=>{});
    let frame=0;
    const pending=new Set<Node>();
    const flush=()=>{
      frame=0;
      pending.forEach(translateNode);
      pending.clear();
    };
    const observer=new MutationObserver(records=>{
      for(const record of records){
        if(record.type==="childList") record.addedNodes.forEach(node=>pending.add(node));
        else if(record.type==="characterData"||record.type==="attributes") pending.add(record.target);
      }
      if(!frame&&pending.size) frame=requestAnimationFrame(flush);
    });
    observer.observe(root,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:["placeholder","title","aria-label"]});
    return ()=>{
      observer.disconnect();
      if(frame) cancelAnimationFrame(frame);
      pending.clear();
    };
  },[locale]);
  return null;
}
